target_left = [
    [1,1,1,1],  # positions: {0,1,2,3}
    [0,1,1,0],  # positions: {1,2}
    [0,1,1,0],  # positions: {1,2}
    [0,0,0,0]   # positions: {}
]

target_right = [
    [2,0,0,0],  # positions: {0}
    [2,2,2,2],  # positions: {0,1,2,3}
    [2,0,0,0],  # positions: {0}
    [0,0,0,0]   # positions: {}
]

result = []
for i in range(4):
    left_pos = set(j for j,v in enumerate(target_left[i]) if v != 0)
    right_pos = set(j for j,v in enumerate(target_right[i]) if v != 0)

    if left_pos & right_pos:  # Has overlap - use LEFT only
        result.append(target_left[i][:])
    else:  # Disjoint - combine both (left first, then right)
        combined = target_left[i][:] + target_right[i][:]
        while len(combined) < 4:
            combined.append(0)
        combined = combined[:4]
        result.append(combined)

print("Predicted output:")
for r in result:
    print(r)

